const timezone = 'America/Guatemala';
const inputDate = new Date($now.toISO());
const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(inputDate).filter((part) => part.type !== 'literal').map((part) => [part.type, Number(part.value)]));
const previous = new Date(Date.UTC(parts.year, parts.month - 2, 1));
const year = previous.getUTCFullYear();
const month = previous.getUTCMonth() + 1;
const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
const iso = (day) => [year, String(month).padStart(2, '0'), String(day).padStart(2, '0')].join('-');
return [{ json: { timezone, period_kind: 'closed_calendar_month', desde: iso(1), hasta: iso(lastDay) } }];

const raw = $json;
const expectedKeys = ['generated_at', 'range', 'report_type', 'schema_version', 'secure_path', 'timezone', 'total'];
const actualKeys = raw && typeof raw === 'object' && !Array.isArray(raw) ? Object.keys(raw).sort() : [];
if (JSON.stringify(actualKeys) !== JSON.stringify(expectedKeys.slice().sort())) throw new Error('CONTRACT_INVALID');
const datePattern = /^\d{4}-\d{2}-\d{2}$/;
const realDate = (value) => { if (typeof value !== 'string' || !datePattern.test(value)) return false; const date = new Date(value + 'T00:00:00Z'); return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === value; };
if (raw.schema_version !== 1 || raw.timezone !== 'America/Guatemala' || raw.report_type !== 'first_prenatal_control_census' || raw.secure_path !== '/reportes') throw new Error('CONTRACT_INVALID');
if (!raw.range || Object.keys(raw.range).sort().join(',') !== 'from,to' || !realDate(raw.range.from) || !realDate(raw.range.to) || raw.range.from > raw.range.to) throw new Error('CONTRACT_INVALID');
if (!Number.isSafeInteger(raw.total) || raw.total < 0 || raw.total > 100000) throw new Error('CONTRACT_INVALID');
const requested = $node['Calcular mes calendario anterior'].json;
if (raw.range.from !== requested.desde || raw.range.to !== requested.hasta) throw new Error('CONTRACT_INVALID');
const hasData = raw.total > 0;
const formatDate = (value) => value.split('-').reverse().join('-');
const fromLabel = formatDate(raw.range.from);
const toLabel = formatDate(raw.range.to);
const subject = 'CAP Prenatal | Censo mensual cerrado | ' + fromLabel + ' al ' + toLabel;
const summary = hasData ? 'Se adjunta el censo de ' + raw.total + ' captadas en primer control.' : 'No se registraron captadas en primer control durante este mes calendario.';
const html = '<div style="font-family:Arial,sans-serif;color:#1f2937;line-height:1.6"><h2 style="color:#7c3aed">Censo de embarazadas: mes calendario cerrado</h2><p><strong>Periodo:</strong> ' + fromLabel + ' al ' + toLabel + '</p><p>' + summary + '</p><p style="font-size:12px;color:#6b7280">Documento confidencial para uso institucional. Proteja los datos de las pacientes.</p></div>';
const filename = 'censo_mes_cerrado_' + fromLabel + '_' + toLabel + '.xlsx';
return [{ json: { subject, html, total: raw.total, has_data: hasData, filename, range_from: raw.range.from, range_to: raw.range.to } }];
